const B64 = '';
let M = null;
export function countryMap() {
  if (M) return M;
  const bin = atob(B64), n = bin.length; M = new Uint8Array(MW * MH);
  let p = 0, k = 0;
  while (k < n) { const v = bin.charCodeAt(k++); let len = 0, sh = 0, c; do { c = bin.charCodeAt(k++); len |= (c & 127) << sh; sh += 7; } while (c & 128); M.fill(v, p, p + len); p += len; }
  return M;
}
// страна в точке (широта, долгота в градусах)
export function countryAt(lat, lon) {
  const m = countryMap();
  const i = Math.min(MW - 1, Math.max(0, Math.floor((lon + 180) / 360 * MW))), j = Math.min(MH - 1, Math.max(0, Math.floor((90 - lat) / 180 * MH)));
  return m[j * MW + i];
}
